use vstd::prelude::*;

verus! {
    // rotate_right takes a non-empty Vec<u32> and a (possibly large) rotation amount n,
    // and returns a new Vec<u32> which is the original Vec rotated to the right by n mod len.
    // If len = list.len(), r = n % len, and s0 = len - r, then
    //   new_list[i] == list[(s0 + i) % len]  for all 0 <= i < len.
    fn rotate_right(list: &Vec<u32>, n: usize) -> (new_list: Vec<u32>)
        requires
            list.len() > 0,
        ensures
        {
            let len = list.len();
            let r   = n % len;
            let s0  = len - r;
            // The result has the same length,
            // and each index i is taken from (s0 + i) mod len of the original.
            new_list.len() == len &&
            forall |i: nat|
                i < len as nat ==>
                    new_list[i as usize] == list[((s0 + (i as usize)) % len)]
        }
    {
        let len = list.len();
        let r   = n % len;
        let s0  = len - r;

        // We'll build up new_list by pushing elements one by one.
        let mut new_list = Vec::new();
        new_list.reserve(len);

        let mut i: usize = 0;
        while i < len
            invariant
                // i never exceeds len
                i <= len,
                // we've pushed exactly i elements so far
                new_list.len() == i,
                // and each pushed element satisfies the rotation property
                forall |j: nat|
                    j < i as nat ==>
                        new_list[j as usize] ==
                            list[((s0 + (j as usize)) % len)],
            decreases
                len - i,
        {
            let idx = (s0 + i) % len;
            new_list.push(list[idx]);
            i += 1;
        }

        new_list
    }
}

fn main() {
    // Example usage:
    let v = vec![10, 20, 30, 40];
    let rotated = rotate_right(&v, 1);
    // rotated == [40,10,20,30]
    assert!(rotated == vec![40,10,20,30]);
}